// Block (composition) — destructive account actions gated by confirmation dialogs.
// ConfirmDialog owns confirmation behavior; Button, Separator, and Stack own their look/layout.
import { Fragment, useId } from "react";
import type { Ref } from "react";
import { Button } from "../components/Button";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import { ConfirmDialog } from "./ConfirmDialog";
import "./DangerZone.css";

export interface DangerZoneProps {
  heading?: string;
  actions: {
    id: string;
    label: string;
    description?: string;
    confirmTitle: string;
    confirmMessage?: string;
    onConfirm?: () => void;
  }[];
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function DangerZone({
  heading = "Danger zone",
  actions,
  className,
  ref,
}: DangerZoneProps) {
  const headingId = useId();

  return (
    <Stack
      as="section"
      ref={ref}
      gap="small"
      aria-labelledby={heading ? headingId : undefined}
      aria-label={heading ? undefined : "Danger zone"}
      className={className ? `sd-dangerzone ${className}` : "sd-dangerzone"}
    >
      {heading && (
        <h2 id={headingId} className="sd-dangerzone__heading sd-type-title-medium">
          {heading}
        </h2>
      )}
      {actions.map((action, index) => (
        <Fragment key={action.id}>
          {index > 0 && <Separator />}
          <Stack
            direction="row"
            justify="between"
            align="center"
            gap="small"
            className="sd-dangerzone__row"
          >
            {action.description && (
              <p className="sd-dangerzone__description sd-type-caption-medium">
                {action.description}
              </p>
            )}
            <ConfirmDialog
              trigger={
                <Button type="button" variant="destructive" size="small" className="sd-dangerzone__action">
                  {action.label}
                </Button>
              }
              title={action.confirmTitle}
              message={action.confirmMessage}
              confirmLabel={action.label}
              onConfirm={action.onConfirm}
              confirmVariant="destructive"
            />
          </Stack>
        </Fragment>
      ))}
    </Stack>
  );
}

/* DangerZone.css — arrangement only; destructive visual treatment remains token-owned. */
.sd-dangerzone {
  width: 100%;
}

.sd-dangerzone__heading,
.sd-dangerzone__description {
  margin: 0;
}

.sd-dangerzone__row,
.sd-dangerzone__description {
  min-width: 0;
}

/* The row gives the description the slack; the action keeps its label on one line. At 390 the
   button was the shrinking item and folded "Delete account" onto two lines. */
.sd-dangerzone__action {
  flex: none;
}
